import{G as e,W as t,n,rt as r}from"./chunks/framework.9o07hMZQ.js";var i=JSON.parse(`{"title":"Prepar3D（P3D）连线教程","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/p3d.md","filePath":"tutorial/p3d.md","lastUpdated":0}`),a={name:`tutorial/p3d.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="prepar3d-p3d-连线教程" tabindex="-1">Prepar3D（P3D）连线教程 <a class="header-anchor" href="#prepar3d-p3d-连线教程" aria-label="Permalink to “Prepar3D（P3D）连线教程”">​</a></h1><p>本教程适用于 Prepar3D（P3D），介绍如何连入 XFLYSIM 连飞服务器。</p><h2 id="准备阶段" tabindex="-1">准备阶段 <a class="header-anchor" href="#准备阶段" aria-label="Permalink to “准备阶段”">​</a></h2><h3 id="_1-安装飞行模拟软件" tabindex="-1">1. 安装飞行模拟软件 <a class="header-anchor" href="#_1-安装飞行模拟软件" aria-label="Permalink to “1. 安装飞行模拟软件”">​</a></h3><ul><li>通过 <a href="https://www.prepar3d.com" target="_blank" rel="noreferrer">Prepar3D 官网</a> 购买并安装 Prepar3D。</li><li>确认已安装最新版本，并完成基础飞行训练（或熟悉基本操作）。</li></ul><h3 id="_2-安装连飞客户端" tabindex="-1">2. 安装连飞客户端 <a class="header-anchor" href="#_2-安装连飞客户端" aria-label="Permalink to “2. 安装连飞客户端”">​</a></h3><ul><li>下载并安装 XFLYSIM 连飞客户端。</li><li>在客户端中填写连飞网站注册的账号与呼号。</li></ul><h3 id="_3-安装语音软件" tabindex="-1">3. 安装语音软件 <a class="header-anchor" href="#_3-安装语音软件" aria-label="Permalink to “3. 安装语音软件”">​</a></h3><ul><li>语音机组需要安装 <strong>XVoice</strong> 语音软件（详见 <a href="/tutorial/xvoice.html">XVoice 语音教程</a>）。</li><li>文字机组可跳过此步骤，在游戏内直接使用文字交流。</li></ul><h2 id="连接步骤" tabindex="-1">连接步骤 <a class="header-anchor" href="#连接步骤" aria-label="Permalink to “连接步骤”">​</a></h2><ol><li>打开 Prepar3D，选择需要飞行的机型和机场。</li><li>将飞机停放在<strong>固定停机位</strong>，等待加载完成。</li><li>启动连飞客户端，填入呼号并连接服务器 <code>ol.xflysim.com</code>。</li><li>连接成功后，第一时间提交飞行计划（起降机场、巡航高度层、计划航路、机型等）。</li><li>在未提供管制服务的空域，使用公用频率 122.800；有管制员在线时听从其指挥。</li></ol><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>严禁在滑行道、跑道上等非停机位直接连线。</li><li>飞行前请仔细阅读<a href="/rules.html">用户准则</a>。</li><li>管制空域内注意收听管制员指令，遵守&quot;左窗避让原则&quot;。</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};